import argparse
import bisect
import json
import pathlib
import re
import timeit
from datetime import datetime, time
from typing import List, Tuple

import cv2
import numpy as np

import utils
from save_analytic_data import *
'''
 Shape of each matrix in npz

 raw_heatmap = ( img_h, img_w, len(obj_type), time_interval/step )
 sample_num = ( len(obj_type), time_interval/step )
 timestamp = ( time_interval/step, step/step_for_count )

 for motion npz, only heatmap is recorded and the sample_num is stored in heatmap[0,0]
 raw_heatmap = ( img_h, img_w ), where sample_num = heatmap[0,0]

 combined motion npz
 raw_heatmap = ( img_h, img_w, time_interval/step )
 sample_num = ( time_interval/step )
 timestamp = ( event_count )
'''


def GetDataFromDB(cam_id: str, start: int, end: int,
                  obj_indexes: List[int]) -> Tuple[np.array, np.array]:
    new_bboxes, id_count = GetEventDataWithTime(cam_id,
                                                start,
                                                end,
                                                is_get_raws=False)
    new_heatmap, new_sample_num = MakeRawHeatmap([new_bboxes], [id_count])
    new_heatmap = np.sum(utils.AdjustDataSize(
        new_heatmap, 2, len(utils.ObjectType))[:, :, obj_indexes, -1],
                         axis=-1)
    new_sample_num = np.sum(
        utils.AdjustDataSize(new_sample_num, 0,
                             len(utils.ObjectType))[obj_indexes, -1])

    return new_heatmap, new_sample_num


def OutputHeatmap(uni_heatmap: np.array, uni_sample_num: int,
                  result_heatmap_path: str) -> None:
    # Make Heatmap
    MAX_CLIP_RATE = 0.5
    max_val = float(uni_sample_num) * MAX_CLIP_RATE
    heatmap = np.clip(uni_heatmap, 0, max_val)
    cv2.normalize(heatmap, heatmap, 0, 255, cv2.NORM_MINMAX)
    heatmap = heatmap.astype(np.uint8)
    opacity = int(255)
    h, w = heatmap.shape
    alpha = np.ones((h, w, 1), dtype=np.uint8) * opacity
    alpha[heatmap[:, :] == 0] = 0
    heatmap = cv2.applyColorMap(heatmap, cv2.COLORMAP_JET)
    heatmap = np.concatenate((heatmap, alpha), axis=-1)

    cv2.imwrite(result_heatmap_path, heatmap)

    # return heatmap for unittest debug usage
    return heatmap


def DrawMotionHeatmap(raw_heatmap_paths: List[pathlib.Path],
                      result_heatmap_path: str, cam_id: str, start_time: int,
                      end_time: int, heatmap_path: pathlib.Path) -> None:
    heatmap_size = utils.HeatmapSize
    data_per_file = []

    # Load npz files
    for path in raw_heatmap_paths:
        is_sum = True if utils.NPZSuffix.SUMMARIZE in path.name else False
        raw_data = utils.LoadNPZ(path)
        if not raw_data: continue

        if 'sample_num' in raw_data and 'timestamp' in raw_data:
            raw_heatmap = raw_data['raw_heatmap']
            sample_num = raw_data['sample_num']
            timestamps = raw_data['timestamp']
            event_only = False
        else:
            raw_heatmap = raw_data['raw_heatmap']
            sample_num = int(raw_heatmap[0, 0])
            raw_heatmap[0, 0] = 0
            timestamps = utils.GetNPZEndTime(path.name, "")
            event_only = True
            # GetAnalyticDataPaths is delibrately getting one more npz after end_time
            # since the npz may contain data before end_time
            # except single event motion npz
            if timestamps > end_time: continue

        # raw heatmap size stick with (h,w)=(90,160) or (90,90) according to the coming ratio
        coming_heatmap_size = raw_heatmap.shape[:2]
        if heatmap_size == utils.HeatmapSize:
            heatmap_size = (utils.MotionHeatmapHeight,
                            int(coming_heatmap_size[1] /
                                coming_heatmap_size[0] *
                                utils.MotionHeatmapHeight))

        if coming_heatmap_size != heatmap_size: continue

        data_per_file.append(
            (raw_heatmap, sample_num, timestamps, is_sum, event_only))

        # no need to append missing time range
        # since all event npzs should be sent to controller from camera
        # and it's not available to get heatmap info from database

    # compute the heatmap
    uni_heatmap = np.zeros(heatmap_size, dtype=np.float32)
    uni_sample_num = 0
    for (h_data, n_data, t_data, is_sum, event_only) in data_per_file:
        if event_only:  # single event only npz
            uni_heatmap += h_data
            uni_sample_num += n_data
            continue

        time_len = len(t_data)
        lo_idx = bisect.bisect_right(t_data, start_time)
        hi_idx = bisect.bisect_left(t_data, end_time)

        if is_sum:  # Summarized npz
            if hi_idx == time_len: hi_idx -= 1
            selected_heatmap = np.sum(h_data[:, :, lo_idx:hi_idx + 1], axis=-1)
            uni_heatmap += selected_heatmap
            uni_sample_num += np.sum(n_data[lo_idx:hi_idx + 1])

            # adjust small time shift
            redundant_times = []
            s_bound = t_data[lo_idx - 1]
            e_bound = t_data[hi_idx]
            if start_time > s_bound:
                redundant_times.append((s_bound, start_time))
            if end_time < e_bound:
                redundant_times.append((end_time, e_bound))
            # get normal npz to remove the rerdundant data
            redundant_npzs = ()
            normal_suffices = [utils.NPZSuffix.COMBINE, utils.NPZSuffix.NORMAL]
            for rs, re in redundant_times:
                for suffix in normal_suffices:
                    redundant_npzs += utils.GetAnalyticDataPaths(
                        heatmap_path,
                        cam_id,
                        rs,
                        re,
                        suffix=suffix,
                        is_motion=True)
                for path in redundant_npzs:
                    raw_data = utils.LoadNPZ(path)
                    if not raw_data: continue
                    if utils.NPZSuffix.COMBINE in path.name:
                        rh_data = raw_data['raw_heatmap']
                        rn_data = raw_data['sample_num']
                        ts = raw_data['timestamp']
                        tl = len(ts)
                        lo = bisect.bisect_right(ts, rs)
                        hi = bisect.bisect_left(ts, re)
                        if lo > hi: continue
                        sh, ssn = SelectNormalMotionData(
                            rh_data,
                            rn_data,
                            lo,
                            hi,
                            tl,
                        )
                    else:
                        ts = utils.GetNPZEndTime(path.name, "")
                        if ts > re: continue
                        sh = raw_data['raw_heatmap']
                        ssn = sh[0, 0]
                        sh[0, 0] = 0
                    if sh.shape != heatmap_size: continue
                    uni_heatmap -= sh
                    uni_sample_num -= ssn

        else:  # Normal npz
            if lo_idx > hi_idx: continue
            sh, ssn = SelectNormalMotionData(
                h_data,
                n_data,
                lo_idx,
                hi_idx,
                time_len,
            )

            uni_heatmap += sh
            uni_sample_num += ssn

    uni_heatmap = cv2.resize(uni_heatmap, tuple(reversed(utils.HeatmapSize)))
    OutputHeatmap(uni_heatmap, uni_sample_num, result_heatmap_path)


def SelectNormalMotionData(h_data: np.array, n_data: np.array, lo_idx: int,
                           hi_idx: int, time_len: int):
    if lo_idx == 0 and hi_idx == time_len:
        selected_heatmap = h_data[:, :, -1]
        selected_sample_num = n_data[-1]
    elif lo_idx != 0 and hi_idx == time_len:
        selected_heatmap = h_data[:, :, hi_idx - 1] - h_data[:, :, lo_idx - 1]
        selected_sample_num = n_data[hi_idx - 1] - n_data[lo_idx - 1]
    elif lo_idx == 0 and hi_idx != time_len:
        selected_heatmap = h_data[:, :, hi_idx]
        selected_sample_num = n_data[hi_idx]
    else:
        selected_heatmap = h_data[:, :, hi_idx] - h_data[:, :, lo_idx - 1]
        selected_sample_num = n_data[hi_idx] - n_data[lo_idx - 1]

    return selected_heatmap, selected_sample_num


def DrawDetectHeatmap(raw_heatmap_paths: List[pathlib.Path],
                      result_heatmap_path: str, cam_id: str, start_time: int,
                      end_time: int, obj_type: set) -> None:
    heatmap_size = utils.HeatmapSize
    data_per_file = []
    missing_time_range = []
    obj_indexes = [utils.ObjectIndex[o_type] for o_type in obj_type]
    is_use_sum = False

    # Load npz files
    for path in raw_heatmap_paths:
        is_sum = True if utils.NPZSuffix.SUMMARIZE in path.name else False
        is_use_sum |= is_sum
        raw_data = utils.LoadNPZ(path)
        if not raw_data: continue
        raw_heatmap = utils.AdjustDataSize(
            raw_data['raw_heatmap'], 2, len(utils.ObjectType))[:, :,
                                                               obj_indexes, :]
        sample_num = utils.AdjustDataSize(
            raw_data['sample_num'], 0, len(utils.ObjectType))[obj_indexes, :]
        timestamps = raw_data['timestamp'][:, -1]
        data_per_file.append((raw_heatmap, sample_num, timestamps, is_sum))

    if not data_per_file:
        print("WARN: No npz data in designated time range {}~{}", start_time,
              end_time)

    # compute the heatmap
    uni_heatmap = np.zeros(heatmap_size, dtype=np.float32)
    uni_sample_num = 0
    for (h_data, n_data, t_data, is_sum) in data_per_file:
        time_len = len(t_data)
        lo_idx = bisect.bisect_right(t_data, start_time)
        hi_idx = bisect.bisect_left(t_data, end_time)

        if is_sum:  # Summarized npz
            if hi_idx == time_len: hi_idx -= 1
            uni_heatmap += np.apply_over_axes(
                np.sum, h_data[:, :, :, lo_idx:hi_idx + 1],
                [-2, -1]).reshape(heatmap_size)
            uni_sample_num += np.sum(n_data[:, lo_idx:hi_idx + 1])

            # adjust small time shift
            s_bound = max(t_data[lo_idx] - utils.TimeStampMS.DAY, 0)
            e_bound = t_data[hi_idx]
            if start_time > s_bound:
                missing_time_range.append((s_bound, start_time))
            if end_time < e_bound:
                missing_time_range.append((end_time, e_bound))

        else:  # Normal npz
            if lo_idx > hi_idx: continue
            sh, ssn = SelectNormalDetectData(
                h_data,
                n_data,
                lo_idx,
                hi_idx,
                time_len,
            )
            uni_heatmap += sh
            uni_sample_num += ssn

    # subtract redundant time range if any
    for s_time, e_time in missing_time_range:
        redundant_npzs = utils.GetAnalyticDataPaths(
            raw_heatmap_paths[-1].parent, cam_id, s_time, e_time)
        if redundant_npzs:
            sh = np.zeros(heatmap_size, dtype=np.float32)
            ssn = 0
            for path in redundant_npzs:
                rd = utils.LoadNPZ(path)
                if not rd: continue
                rh_data = utils.AdjustDataSize(
                    rd['raw_heatmap'], 2,
                    len(utils.ObjectType))[:, :, obj_indexes, :]
                rn_data = utils.AdjustDataSize(
                    rd['sample_num'], 0, len(utils.ObjectType))[obj_indexes, :]
                ts = rd['timestamp'][:, -1]
                tl = len(ts)
                lo = bisect.bisect_right(ts, s_time)
                hi = bisect.bisect_left(ts, e_time)
                if lo > hi: continue
                sh, ssn = SelectNormalDetectData(
                    rh_data,
                    rn_data,
                    lo,
                    hi,
                    tl,
                )
                uni_heatmap -= sh
                uni_sample_num -= ssn

    OutputHeatmap(uni_heatmap, uni_sample_num, result_heatmap_path)


def SelectNormalDetectData(h_data: np.array, n_data: np.array, lo_idx: int,
                           hi_idx: int, time_len: int):
    selected_heatmap = np.zeros(utils.HeatmapSize, dtype=np.float32)
    selected_sample_num = 0
    if lo_idx == 0 and hi_idx == time_len:
        selected_heatmap = np.sum(h_data[:, :, :, -1],
                                  axis=-1).reshape(utils.HeatmapSize)
        selected_sample_num = np.sum(n_data[:, -1])
    elif lo_idx != 0 and hi_idx == time_len:
        selected_heatmap = np.sum(h_data[:, :, :, hi_idx - 1] -
                                  h_data[:, :, :, lo_idx - 1],
                                  axis=-1).reshape(utils.HeatmapSize)
        selected_sample_num = np.sum(n_data[:, hi_idx - 1] -
                                     n_data[:, lo_idx - 1])
    elif lo_idx == 0 and hi_idx != time_len:
        selected_heatmap = np.sum(h_data[:, :, :, hi_idx],
                                  axis=-1).reshape(utils.HeatmapSize)
        selected_sample_num = np.sum(n_data[:, hi_idx])
    else:
        selected_heatmap = np.sum(h_data[:, :, :, hi_idx] -
                                  h_data[:, :, :, lo_idx - 1],
                                  axis=-1).reshape(utils.HeatmapSize)
        selected_sample_num = np.sum(n_data[:, hi_idx] - n_data[:, lo_idx - 1])

    return selected_heatmap, selected_sample_num


def Main():
    parser = argparse.ArgumentParser(
        "Draw Smart Detect/Motion heatmap in certain time range")

    parser.add_argument(
        "-id",
        dest="cam_id",
        nargs='+',
        help='target camera id to draw heatmap, multiple ids are allowed',
        type=str)
    parser.add_argument("-heatmap",
                        dest="heatmap_path",
                        help='raw heatmap directory path',
                        type=str)
    parser.add_argument('-s',
                        dest='start_time',
                        help='start timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument('-e',
                        dest='end_time',
                        help='end timestamp (ms) of desired interval',
                        type=int)
    parser.add_argument(
        '-type',
        dest='obj_type',
        nargs='+',
        type=str,
        help=
        'object type to include in the heatmap (motion, person, vehicle, all(motion excluded))'
    )

    args = parser.parse_args()

    heatmap_path = pathlib.Path(args.heatmap_path)

    if not heatmap_path.is_dir():
        raise FileNotFoundError(
            "Cannot find heatmap dir [{}]".format(heatmap_path))

    # Round time to the nearest sharp time
    start_time = utils.RoundTimeToNearestMin(args.start_time,
                                             60,
                                             return_ts=True)
    end_time = utils.RoundTimeToNearestMin(args.end_time, 60, return_ts=True)

    if 'unittest' in args.cam_id:
        start_time = args.start_time
        end_time = args.end_time

    now = int(datetime.now().timestamp() * 1000)
    if end_time - now > 0:  # make sure end_time doesn't exceed current time
        end_time = utils.FloorTimeToNearestMin(now, 60, return_ts=True)

    if start_time > end_time:
        raise ValueError("start time is later than end time")

    is_motion = False
    if not args.obj_type or 'all' in args.obj_type:
        obj_type = utils.ObjectType
    elif 'motion' in args.obj_type:
        obj_type = set(["motion"])  # motion cannot mix with other types
        is_motion = True
    else:
        obj_type = set(args.obj_type)

    if obj_type - (utils.ObjectType | set(['motion'])):
        raise ValueError(
            "invalid object type [{}] included, should be [{}]".format(
                obj_type - (utils.ObjectType | set(['motion'])),
                utils.ObjectType | set(['motion'])))

    heatmap_objtype_str = 'all'
    if obj_type < utils.ObjectType or obj_type == set(['motion']):
        heatmap_objtype_str = '_'.join(sorted(obj_type))

    if args.cam_id:
        for cam_id in args.cam_id:
            result_heatmap_path = "/tmp/{}_heatmap_{}_{}_{}.png".format(
                cam_id, heatmap_objtype_str, start_time, end_time)

            name_cnt = 0
            while pathlib.Path(result_heatmap_path).exists():
                name_cnt += 1
                result_heatmap_path = re.sub(r"(_\([0-9]\))?.png",
                                             "_({}).png".format(name_cnt),
                                             result_heatmap_path)

            is_get_normal = True
            suffices = [utils.NPZSuffix.NORMAL]
            if is_motion: suffices.append(utils.NPZSuffix.COMBINE)

            raw_heatmap_path = ()
            if end_time - start_time >= utils.TimeStampMS.WEEK:
                # Try to get Summarized NPZ
                raw_heatmap_path += utils.GetAnalyticDataPaths(
                    heatmap_path, cam_id, start_time, end_time,
                    utils.NPZSuffix.SUMMARIZE, is_motion)
                if raw_heatmap_path:
                    is_get_normal = False
                    sum_first = utils.GetNPZEndTime(
                        raw_heatmap_path[0].name,
                        utils.NPZSuffix.SUMMARIZE) - utils.TimeStampMS.WEEK
                    sum_end = utils.GetNPZEndTime(raw_heatmap_path[-1].name,
                                                  utils.NPZSuffix.SUMMARIZE)
                    # get normal files that not recorded in summarized npz
                    for suffix in suffices:
                        if start_time < sum_first:
                            raw_heatmap_path += utils.GetAnalyticDataPaths(
                                heatmap_path,
                                cam_id,
                                start_time,
                                sum_first,
                                suffix=suffix,
                                is_motion=is_motion)
                        if end_time > sum_end:
                            raw_heatmap_path += utils.GetAnalyticDataPaths(
                                heatmap_path,
                                cam_id,
                                sum_end,
                                end_time,
                                suffix=suffix,
                                is_motion=is_motion)

            if is_get_normal:
                for suffix in suffices:
                    raw_heatmap_path += utils.GetAnalyticDataPaths(
                        heatmap_path,
                        cam_id,
                        start_time,
                        end_time,
                        suffix=suffix,
                        is_motion=is_motion)

            if is_motion:
                DrawMotionHeatmap(raw_heatmap_path, result_heatmap_path,
                                  cam_id, start_time, end_time, heatmap_path)
            else:
                DrawDetectHeatmap(raw_heatmap_path, result_heatmap_path,
                                  cam_id, start_time, end_time, obj_type)

            result_json_output = {
                cam_id: {
                    "timestamp": [start_time, end_time],
                    "heatmap": result_heatmap_path
                }
            }
            print(json.dumps(result_json_output))  # for BE to parse


if __name__ == "__main__":
    Main()
